// App.js
import React from 'react';
import ReactDOM from 'react-dom';
import {
  DataTable,
  TableContainer,
  Table,
  TableHead,
  TableRow,
  TableHeader,
  TableBody,
  TableCell,
} from 'carbon-components-react';
import 'carbon-components/css/carbon-components.min.css';

const rows = [
  { id: 'a', name: 'Load balancer 1', status: 'Disabled' },
  { id: 'b', name: 'Load balancer 2', status: 'Starting' },
  { id: 'c', name: 'Load balancer 3', status: 'Active' },
];

const headers = [
  { key: 'name', header: 'Name' },
  { key: 'status', header: 'Status' },
];

function App() {
  return (
    <div style={{ padding: '2rem' }}>
      <DataTable rows={rows} headers={headers}>
        {({ rows, headers, getTableProps, getTableContainerProps, getHeaderProps, getRowProps }) => (
          // TableContainer renders title + description but does not add IDs or wire up aria-* on the <table>
          <TableContainer
            title="Table title"
            description="Table description"
            {...getTableContainerProps()}>
            <Table {...getTableProps()}>
              <TableHead>
                <TableRow>
                  {headers.map((h) => (
                    <TableHeader key={h.key} {...getHeaderProps({ header: h })}>
                      {h.header}
                    </TableHeader>
                  ))}
                </TableRow>
              </TableHead>
              <TableBody>
                {rows.map((r) => (
                  <TableRow key={r.id} {...getRowProps({ row: r })}>
                    {r.cells.map((cell) => (
                      <TableCell key={cell.id}>{cell.value}</TableCell>
                    ))}
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        )}
      </DataTable>
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
